package net.civeira.phylax.features.notification.message.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RetriesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property retries of message ")
  void test_retries_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RetriesVO.tryFrom(null));
    Assertions.assertEquals(1, RetriesVO.from(1).getRetries());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RetriesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RetriesVO.from(1).toString());
  }
}
